-- CodeVenjar AI production schema for Supabase/PostgreSQL.
-- Run this entire file once in Supabase SQL Editor.
create extension if not exists pgcrypto;

create or replace function public.make_learner_id() returns text language sql stable as $$
  select 'CV-' || to_char(current_date, 'YYYY') || '-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));
$$;

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  learner_id text unique not null default public.make_learner_id(),
  full_name text, target_role text not null default 'Data Analyst', hours_per_week text default '3–5 hours',
  project_goal text, roadmap jsonb, status text not null default 'Learning', created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
alter table public.profiles add column if not exists role text not null default 'candidate';
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$
begin insert into public.profiles (id,full_name,role) values (new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),coalesce(new.raw_user_meta_data->>'role','candidate')) on conflict (id) do nothing; return new; end;
$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

create table if not exists public.skills (
  id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade,
  skill_name text not null, confidence integer not null default 0 check (confidence between 0 and 100), updated_at timestamptz not null default now(), unique(user_id,skill_name)
);
create table if not exists public.course_catalog (
  id text primary key, title text not null, description text not null, level text not null, duration text not null,
  price_inr integer not null default 0 check (price_inr >= 0), skills text[] not null default '{}', outcome text,
  delivery_mode text not null default 'Recorded' check (delivery_mode in ('Live','Recorded')), access_details text,
  notes text[] not null default '{}', is_active boolean not null default true, created_at timestamptz not null default now()
);
create table if not exists public.enrollments (
  id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade,
  course_id text not null references public.course_catalog(id), status text not null default 'pending' check (status in ('pending','enrolled','completed','cancelled')),
  progress integer not null default 0 check (progress between 0 and 100), enrolled_at timestamptz not null default now(), unique(user_id,course_id)
);
create table if not exists public.payments (
  id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade,
  enrollment_id bigint references public.enrollments(id) on delete set null, provider text not null default 'manual_or_razorpay',
  provider_payment_id text, payment_method text, amount_inr integer not null default 0 check (amount_inr >= 0),
  status text not null default 'created' check (status in ('created','paid','failed','refunded')), created_at timestamptz not null default now()
);
create table if not exists public.mentors (
  id text primary key, name text not null, role text not null, specialty text not null, rating numeric(2,1), availability text, bio text, is_active boolean not null default true
);
create table if not exists public.mentor_bookings (
  id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade,
  mentor_id text not null references public.mentors(id), slot text not null, note text,
  status text not null default 'requested' check (status in ('requested','confirmed','completed','cancelled')), created_at timestamptz not null default now()
);
create table if not exists public.assignments (
  id text primary key, title text not null, topic text not null, difficulty text not null, estimated_minutes integer not null, prompt text not null, answer_hint text
);
create table if not exists public.assignment_submissions (
  id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade,
  assignment_id text not null references public.assignments(id), answer text, status text not null default 'submitted' check (status in ('started','submitted','reviewed')),
  score integer check (score between 0 and 100), submitted_at timestamptz not null default now()
);
create table if not exists public.portfolio_profiles (
  user_id uuid primary key references auth.users(id) on delete cascade, display_name text not null, headline text, bio text, location text, featured_project text, skills text[] not null default '{}', updated_at timestamptz not null default now()
);
create table if not exists public.learner_records (
  id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, learner_id text not null, record_type text not null, title text not null, detail text, created_at timestamptz not null default now()
);
create table if not exists public.activity_events (
  id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, event_type text not null, event_name text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()
);
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());

alter table public.profiles enable row level security; alter table public.skills enable row level security; alter table public.course_catalog enable row level security;
alter table public.enrollments enable row level security; alter table public.payments enable row level security; alter table public.mentors enable row level security;
alter table public.mentor_bookings enable row level security; alter table public.assignments enable row level security; alter table public.assignment_submissions enable row level security;
alter table public.portfolio_profiles enable row level security; alter table public.learner_records enable row level security; alter table public.activity_events enable row level security; alter table public.admin_users enable row level security;

create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()); $$;

drop policy if exists profiles_owner on public.profiles; create policy profiles_owner on public.profiles for all using (auth.uid()=id or public.is_admin()) with check (auth.uid()=id or public.is_admin());
drop policy if exists skills_owner on public.skills; create policy skills_owner on public.skills for all using (auth.uid()=user_id or public.is_admin()) with check (auth.uid()=user_id or public.is_admin());
drop policy if exists courses_read on public.course_catalog; create policy courses_read on public.course_catalog for select using (is_active=true or public.is_admin());
drop policy if exists enrollments_owner on public.enrollments; create policy enrollments_owner on public.enrollments for all using (auth.uid()=user_id or public.is_admin()) with check (auth.uid()=user_id or public.is_admin());
drop policy if exists payments_owner on public.payments; create policy payments_owner on public.payments for all using (auth.uid()=user_id or public.is_admin()) with check (auth.uid()=user_id or public.is_admin());
drop policy if exists mentors_read on public.mentors; create policy mentors_read on public.mentors for select using (is_active=true or public.is_admin());
drop policy if exists bookings_owner on public.mentor_bookings; create policy bookings_owner on public.mentor_bookings for all using (auth.uid()=user_id or public.is_admin()) with check (auth.uid()=user_id or public.is_admin());
drop policy if exists assignments_read on public.assignments; create policy assignments_read on public.assignments for select using (true);
drop policy if exists submissions_owner on public.assignment_submissions; create policy submissions_owner on public.assignment_submissions for all using (auth.uid()=user_id or public.is_admin()) with check (auth.uid()=user_id or public.is_admin());
drop policy if exists portfolio_owner on public.portfolio_profiles; create policy portfolio_owner on public.portfolio_profiles for all using (auth.uid()=user_id or public.is_admin()) with check (auth.uid()=user_id or public.is_admin());
drop policy if exists records_owner on public.learner_records; create policy records_owner on public.learner_records for all using (auth.uid()=user_id or public.is_admin()) with check (auth.uid()=user_id or public.is_admin());
drop policy if exists activity_owner on public.activity_events; create policy activity_owner on public.activity_events for all using (auth.uid()=user_id or public.is_admin()) with check (auth.uid()=user_id or public.is_admin());
drop policy if exists admin_self on public.admin_users; create policy admin_self on public.admin_users for select using (auth.uid()=user_id);

create or replace function public.admin_activity_overview() returns table(learner_id text,email text,last_active timestamptz,event_count bigint)
language sql security definer set search_path=public as $$
select p.learner_id,u.email,max(a.created_at),count(a.id) from public.profiles p join auth.users u on u.id=p.id left join public.activity_events a on a.user_id=p.id where public.is_admin() group by p.learner_id,u.email order by max(a.created_at) desc nulls last;
$$;
grant execute on function public.admin_activity_overview() to authenticated;

